def max_product(arr):
    if not arr:
        return 0

    n = len(arr)
    dp = arr[:]  # dp[i] max product of increasing subsequence ending at i

    for i in range(1, n):
        for j in range(i):
            if arr[j] < arr[i]:
                dp[i] = max(dp[i], dp[j] * arr[i])

    return max(dp)


assert max_product([3, 100, 4, 5, 150, 6]) == 3000
assert max_product([1, 2, 3, 4]) == 24  # 1*2*3*4=24
assert max_product([4, 3, 2, 1]) == 4   # decreasing sequence, max single element=4
assert max_product([10]) == 10          # single element
assert max_product([]) == 0             # empty array
assert max_product([1, 3, 2, 6, 4, 8]) == 144  # subsequence: 1,3,6,8 = 144
assert max_product([5, 6, 3, 7, 2, 8]) == 168  # subsequence: 5,6,7,8 = 168
assert max_product([1, 2, 2, 2, 3]) == 6        # subsequence: 1,2,3 = 6, duplicates handled
